INSERT INTO `iz` (`ev_broj`, `vr_broj`, `tip`, `koda`, `ser_br`, `datum`, `izdanje`, `detalj`, `lokacija`, `opis`, `prijem`, `primio`, `serviser`, `izdao`, `dat_ser`, `dat_poc`, `kuciste`) VALUES
(5, 0, 'KRS', '465-436-700', '1167 MS', '2019-03-13 12:23:34', '1978', '', 'Pazarić', 'Zamjenjeno je kućište uređaja i očišćeni su kontakti releja. Kućišta osigurača, osigurači i signalne sijalice su pregledani i izvršena je izmjena istih ako su oštećeni(vidi zamijenjene elemente). Natpisne letvice releja su zamjenjene novim. Konektori uređaja su pregledani, očišćeni i izvršen je test uklapanja konektora u odgovarajućem mjestu u ramu. Namotaji releja su ispitani dovođenjem istosmjernog napona preko zaštitnog otpornika ili direktno na pojedine namotaje u zavisnosti od tipa ispitanog releja. Ostale komponente uređaja su ispitane i izvršena je izmjena istih u slučaju neispravnog rada.', '', '', '', '', '2018-02-14', '2018-02-13', '?'),
(9, 0, 'RGS', '465-406-503', '221 343', '2021-12-06 06:39:47', '1982', '', 'TE Tuzla', 'Zamjenjeno je kućište uređaja i očišćeni su kontakti releja. Kućišta osigurača, osigurači i signalne sijalice su pregledani i izvršena je izmjena istih ako su oštećeni(vidi zamijenjene elemente). Natpisne letvice releja su zamjenjene novim. Konektori uređaja su pregledani, očišćeni i izvršen je test uklapanja konektora u odgovarajućem mjestu u ramu. Namotaji releja su ispitani dovođenjem istosmjernog napona preko zaštitnog otpornika ili direktno na pojedine namotaje u zavisnosti od tipa ispitanog releja. Ostale komponente uređaja su ispitane i izvršena je izmjena istih u slučaju neispravnog rada.', '', '', 'Faruk Bahtić', 'Asad Tabak', '2019-03-13', '2018-01-10', 'Novo kućište - stara boja'),
