INSERT INTO `ser` (`ev_broj`, `vr_broj`, `tip`, `koda`, `ser_br`, `datum`, `izdanje`, `detalj`, `lokacija`, `prijem`, `kuciste`, `opis`, `primio`, `serviser`, `dat_poc`) VALUES
(1, 0, 'KRS', '465-436-701', '231137', '2019-03-13 11:20:57', '1982', 'Mido', 'STEP', 'Za potrebe STEP-a', 'Novo kućište - stara boja', 'Zamjenjeno je kućište uređaja i očišćeni su kontakti releja. Kućišta osigurača, osigurači i signalne sijalice su pregledani i izvršena je izmjena istih ako su oštećeni(vidi zamijenjene elemente). Natpisne letvice releja su zamjenjene novim. Konektori uređaja su pregledani, očišćeni i izvršen je test uklapanja konektora u odgovarajućem mjestu u ramu. Namotaji releja su ispitani dovođenjem istosmjernog napona preko zaštitnog otpornika ili direktno na pojedine namotaje u zavisnosti od tipa ispitanog releja. Ostale komponente uređaja su ispitane i izvršena je izmjena istih u slučaju neispravnog rada.', '', 'Faruk Bahtić', '2018-03-05'),
