INSERT INTO `vracene` (`ev_broj`, `vr_broj`, `tip`, `koda`, `ser_br`, `datum`, `izdanje`, `lokacija`, `detalj`, `opis`, `prijem`, `kuciste`, `primio`) VALUES
(23, 1, 'VGS', '471-008-504', '5989 KS', '2022-12-26 08:36:28', '1976', 'Zenica', 'Zenica', 'Zamjenjeno je kućište uređaja i očišćeni su kontakti releja. Kućišta osigurača, osigurači i signalne sijalice su pregledani i izvršena je izmjena istih ako su oštećeni(vidi zamijenjene elemente). Natpisne letvice releja su zamjenjene novim. Konektori uređaja su pregledani, očišćeni i izvršen je test uklapanja konektora u odgovarajućem mjestu u ramu. Namotaji releja su ispitani dovođenjem istosmjernog napona preko zaštitnog otpornika ili direktno na pojedine namotaje u zavisnosti od tipa ispitanog releja. Ostale komponente uređaja su ispitane i izvršena je izmjena istih u slučaju neispravnog rada.', 'Bez fizičkih oštećenja', '', 'Edin Šatrović'),
(121, 1, 'VGS', '471-008-504', '1050556', '2022-10-17 07:34:55', '2010', 'Mostar', 'Mostar', 'Očišćeno je kućište uređaja i očišćeni su kontakti releja. Konektori uređaja su pregledani. Namotaji releja su ispitani dovođenjem istosmjernog napona preko zaštitnog otpornika ili direktno na pojedine namotaje u zavisnosti od tipa ispitanog releja. Ostale komponente uređaja su ispitane i izvršena je izmjena istih u slučaju neispravnog rada. Uređaj je testiran na signalu i spreman je za upotrebu.', 'Bez fizičkih oštećenja.', '', 'Asad Tabak'),
